namespace AccessControl;

public sealed class AccessDecisionEngine
{
    public AccessDecision Decide(Principal? principal, Resource? resource, AccessRequest? request, IDelegationRegister delegations)
    {
        if (principal is null || resource is null || request is null)
            return new AccessDecision(false, "missing-context", true);

        if (TryValidateContext(principal, resource, request, out var validationFailure))
            return validationFailure;

        var authorization = GetAuthorization(principal, resource, request, delegations);

        if (TryEvaluateBreakGlass(request, authorization, out var breakGlassDecision))
            return breakGlassDecision;
        if (TryEvaluateClassification(resource, request, out var classificationDecision))
            return classificationDecision;
        if (TryEvaluateAction(request, authorization, out var actionDecision))
            return actionDecision;

        var outsideBusinessHours = request.MinuteOfDay < 480 || request.MinuteOfDay > 1080;
        return new AccessDecision(
            true,
            authorization.Delegated ? "delegated" : "role-or-ownership",
            outsideBusinessHours || resource.Classification == "restricted");
    }

    private static bool TryValidateContext(
        Principal principal,
        Resource resource,
        AccessRequest request,
        out AccessDecision decision)
    {
        if (string.IsNullOrWhiteSpace(principal.Id) || string.IsNullOrWhiteSpace(resource.Id))
        {
            decision = new AccessDecision(false, "invalid-identity", true);
            return true;
        }

        if (principal.Suspended)
        {
            decision = new AccessDecision(false, "principal-suspended", true);
            return true;
        }

        if (!string.Equals(principal.TenantId, resource.TenantId, StringComparison.Ordinal))
        {
            decision = new AccessDecision(false, "tenant-mismatch", true);
            return true;
        }

        if (resource.Locked && request.Action != "read")
        {
            decision = new AccessDecision(false, "resource-locked", true);
            return true;
        }

        if (request.MinuteOfDay is < 0 or > 1439)
        {
            decision = new AccessDecision(false, "invalid-time", true);
            return true;
        }

        if (principal.FailedChallenges >= 3 && !request.StrongAuthentication)
        {
            decision = new AccessDecision(false, "challenge-required", true);
            return true;
        }

        decision = default!;
        return false;
    }

    private static Authorization GetAuthorization(
        Principal principal,
        Resource resource,
        AccessRequest request,
        IDelegationRegister delegations)
    {
        var administrator = principal.Roles.Contains("administrator");
        var operatorRole = principal.Roles.Contains("operator");
        var auditor = principal.Roles.Contains("auditor");
        var owner = principal.Id == resource.OwnerId;
        var delegated = delegations.HasDelegation(principal.Id, resource.Id, request.Action);

        return new Authorization(administrator, operatorRole, auditor, owner, delegated);
    }

    private static bool TryEvaluateBreakGlass(
        AccessRequest request,
        Authorization authorization,
        out AccessDecision decision)
    {
        if (!request.BreakGlass)
        {
            decision = default!;
            return false;
        }

        decision = !authorization.Administrator || !request.StrongAuthentication
            ? new AccessDecision(false, "invalid-break-glass", true)
            : new AccessDecision(true, "break-glass", true);
        return true;
    }

    private static bool TryEvaluateClassification(
        Resource resource,
        AccessRequest request,
        out AccessDecision decision)
    {
        if (resource.Classification == "restricted" && !request.StrongAuthentication)
        {
            decision = new AccessDecision(false, "strong-authentication-required", true);
            return true;
        }

        if (resource.Classification == "restricted" && request.NetworkZone != "trusted")
        {
            decision = new AccessDecision(false, "trusted-network-required", true);
            return true;
        }

        decision = default!;
        return false;
    }

    private static bool TryEvaluateAction(
        AccessRequest request,
        Authorization authorization,
        out AccessDecision decision)
    {
        if (request.Action == "delete" && !authorization.Administrator)
        {
            decision = new AccessDecision(false, "administrator-required", true);
            return true;
        }

        if (request.Action == "write" && !authorization.CanWrite)
        {
            decision = new AccessDecision(false, "write-not-authorised", true);
            return true;
        }

        if (request.Action == "read" && !authorization.CanRead)
        {
            decision = new AccessDecision(false, "read-not-authorised", false);
            return true;
        }

        if (request.Action is not ("read" or "write" or "delete"))
        {
            decision = new AccessDecision(false, "unknown-action", true);
            return true;
        }

        decision = default!;
        return false;
    }

    private readonly struct Authorization
    {
        public Authorization(bool administrator, bool operatorRole, bool auditor, bool owner, bool delegated)
        {
            Administrator = administrator;
            OperatorRole = operatorRole;
            Auditor = auditor;
            Owner = owner;
            Delegated = delegated;
        }

        public bool Administrator { get; }
        public bool OperatorRole { get; }
        public bool Auditor { get; }
        public bool Owner { get; }
        public bool Delegated { get; }
        public bool CanWrite => Administrator || OperatorRole || Owner || Delegated;
        public bool CanRead => Administrator || OperatorRole || Auditor || Owner || Delegated;
    }
}
